import sqlite3,json
out={}
for aid in ['006','005','001']:
 c=sqlite3.connect('file:/var/ossec/queue/db/'+aid+'.db?mode=ro',uri=True);c.row_factory=sqlite3.Row
 queries={'policies':'select * from sca_policy','scan':'select * from sca_scan_info','checks':"select id,policy_id,title,result,reason,condition,command from sca_check where lower(title) like '%ssh%' or lower(title) like '%firewall%' limit 12",'os':'select hostname,os_name,os_version,release,scan_time from sys_osinfo','packages':"select name,version,architecture,format,scan_time from sys_programs where name in ('xz-utils','liblzma5','openssh-server','openssh-client','lxd') or name like '%7-Zip%'"}
 out[aid]={k:[dict(r) for r in c.execute(q)] for k,q in queries.items()}
print(json.dumps(out,ensure_ascii=False))

PY
